module ex257_umul_csa_concat_cla(in, out);
  input [11:0] in;
  output [11:0] out;
  wire [5:0] a = in[5:0];
  wire [5:0] b = in[11:6];
  wire [11:0] row0 = {{6{1'b0}}, (a & {6{b[0]}})};
  wire [11:0] row1 = {{5{1'b0}}, (a & {6{b[1]}}), {1{1'b0}}};
  wire [11:0] row2 = {{4{1'b0}}, (a & {6{b[2]}}), {2{1'b0}}};
  wire [11:0] row3 = {{3{1'b0}}, (a & {6{b[3]}}), {3{1'b0}}};
  wire [11:0] row4 = {{2{1'b0}}, (a & {6{b[4]}}), {4{1'b0}}};
  wire [11:0] row5 = {{1{1'b0}}, (a & {6{b[5]}}), {5{1'b0}}};
  wire [11:0] s0_0 = row0 ^ row1 ^ row2;
  wire [11:0] c0_0 = ((row0 & row1) | (row0 & row2) | (row1 & row2)) << 1;
  wire [11:0] s0_1 = row3 ^ row4 ^ row5;
  wire [11:0] c0_1 = ((row3 & row4) | (row3 & row5) | (row4 & row5)) << 1;
