  assign cla_sum[8] = cla_p[8] ^ (cla_g[7] | (cla_p[7] & cla_g[6]) | (cla_p[6] & cla_p[7] & cla_g[5]) | (cla_p[5] & cla_p[6] & cla_p[7] & cla_g[4]) | (cla_p[4] & cla_p[5] & cla_p[6] & cla_p[7] & cla_g[3]) | (cla_p[3] & cla_p[4] & cla_p[5] & cla_p[6] & cla_p[7] & cla_g[2]) | (cla_p[2] & cla_p[3] & cla_p[4] & cla_p[5] & cla_p[6] & cla_p[7] & cla_g[1]) | (cla_p[1] & cla_p[2] & cla_p[3] & cla_p[4] & cla_p[5] & cla_p[6] & cla_p[7] & cla_g[0]));
  assign cla_sum[9] = cla_p[9] ^ (cla_g[8] | (cla_p[8] & cla_g[7]) | (cla_p[7] & cla_p[8] & cla_g[6]) | (cla_p[6] & cla_p[7] & cla_p[8] & cla_g[5]) | (cla_p[5] & cla_p[6] & cla_p[7] & cla_p[8] & cla_g[4]) | (cla_p[4] & cla_p[5] & cla_p[6] & cla_p[7] & cla_p[8] & cla_g[3]) | (cla_p[3] & cla_p[4] & cla_p[5] & cla_p[6] & cla_p[7] & cla_p[8] & cla_g[2]) | (cla_p[2] & cla_p[3] & cla_p[4] & cla_p[5] & cla_p[6] & cla_p[7] & cla_p[8] & cla_g[1]) | (cla_p[1] & cla_p[2] & cla_p[3] & cla_p[4] & cla_p[5] & cla_p[6] & cla_p[7] & cla_p[8] & cla_g[0]));
  assign cla_sum[10] = cla_p[10] ^ (cla_g[9] | (cla_p[9] & cla_g[8]) | (cla_p[8] & cla_p[9] & cla_g[7]) | (cla_p[7] & cla_p[8] & cla_p[9] & cla_g[6]) | (cla_p[6] & cla_p[7] & cla_p[8] & cla_p[9] & cla_g[5]) | (cla_p[5] & cla_p[6] & cla_p[7] & cla_p[8] & cla_p[9] & cla_g[4]) | (cla_p[4] & cla_p[5] & cla_p[6] & cla_p[7] & cla_p[8] & cla_p[9] & cla_g[3]) | (cla_p[3] & cla_p[4] & cla_p[5] & cla_p[6] & cla_p[7] & cla_p[8] & cla_p[9] & cla_g[2]) | (cla_p[2] & cla_p[3] & cla_p[4] & cla_p[5] & cla_p[6] & cla_p[7] & cla_p[8] & cla_p[9] & cla_g[1]) | (cla_p[1] & cla_p[2] & cla_p[3] & cla_p[4] & cla_p[5] & cla_p[6] & cla_p[7] & cla_p[8] & cla_p[9] & cla_g[0]));
  assign cla_sum[11] = cla_p[11] ^ (cla_g[10] | (cla_p[10] & cla_g[9]) | (cla_p[9] & cla_p[10] & cla_g[8]) | (cla_p[8] & cla_p[9] & cla_p[10] & cla_g[7]) | (cla_p[7] & cla_p[8] & cla_p[9] & cla_p[10] & cla_g[6]) | (cla_p[6] & cla_p[7] & cla_p[8] & cla_p[9] & cla_p[10] & cla_g[5]) | (cla_p[5] & cla_p[6] & cla_p[7] & cla_p[8] & cla_p[9] & cla_p[10] & cla_g[4]) | (cla_p[4] & cla_p[5] & cla_p[6] & cla_p[7] & cla_p[8] & cla_p[9] & cla_p[10] & cla_g[3]) | (cla_p[3] & cla_p[4] & cla_p[5] & cla_p[6] & cla_p[7] & cla_p[8] & cla_p[9] & cla_p[10] & cla_g[2]) | (cla_p[2] & cla_p[3] & cla_p[4] & cla_p[5] & cla_p[6] & cla_p[7] & cla_p[8] & cla_p[9] & cla_p[10] & cla_g[1]) | (cla_p[1] & cla_p[2] & cla_p[3] & cla_p[4] & cla_p[5] & cla_p[6] & cla_p[7] & cla_p[8] & cla_p[9] & cla_p[10] & cla_g[0]));
